import java.util.*;
public class Main {
    static class Trie { Map<Character, Trie> children = new HashMap<>(); boolean end; }
    public static void main(String[] args) {
        Trie root = new Trie();
        for (String word : new String[]{"cat", "car"}) {
            Trie node = root;
            for (char ch : word.toCharArray()) node = node.children.computeIfAbsent(ch, k -> new Trie());
            node.end = true;
        }
        Trie node = root;
        for (char ch : "cat".toCharArray()) node = node.children.get(ch);
        System.out.println(node.end + " " + root.children.get('c').children.containsKey('r'));
    }
}
